class Person:
    """使用 @dataclass 装饰器的类（decorated_definition）"""

    name: str
    age: int
    email: str | None = None

    def __post_init__(self):
        """数据类的初始化后处理"""
        if self.age < 0:
            raise ValueError("年龄不能为负")

    def greet(self) -> str:
        """问候方法"""
        return f"你好，我是 {self.name}"

class PropertyExample:
    """属性装饰器示例（decorated_definition）"""

    def __init__(self, value: int):
        self._value = value

    @property
    def value(self) -> int:
        """使用 @property 装饰器（decorated_definition）"""
        return self._value

    @value.setter
    def value(self, val: int) -> None:
        """属性 setter（decorated_definition）"""
        self._value = val

    @staticmethod
    def static_method() -> str:
        """静态方法（decorated_definition）"""
        return "静态方法"

    @classmethod
    def class_method(cls) -> str:
        """类方法（decorated_definition）"""
        return f"类方法：{cls.__name__}"

class Animal(ABC):
    """抽象基类"""

    def __init__(self, name: str, species: str):
        self.name = name
        self.species = species

    @abstractmethod
    def make_sound(self) -> str:
        """抽象方法（必须被子类实现）"""
        pass

    def describe(self) -> str:
        """普通方法"""
        return f"{self.name} 是一只 {self.species}"

class Dog(Animal):
    """继承自 Animal 的子类"""

    def __init__(self, name: str, breed: str):
        super().__init__(name, "狗")
        self.breed = breed

    def make_sound(self) -> str:
        """实现抽象方法"""
        return "汪汪！"

    def fetch(self, item: str) -> str:
        """狗的特有方法"""
        return f"{self.name} 捡回了 {item}"

class NestedClassExample:
    """嵌套类示例"""

    class Inner:
        """内部类"""

        def inner_method(self) -> str:
            return "内部方法"

    def outer_method(self) -> str:
        """外部方法"""
        return "外部方法"

class Inner:
        """内部类"""

        def inner_method(self) -> str:
            return "内部方法"

class ComplexNesting:
    """复杂嵌套结构（测试深度遍历）"""

    def level1_method(self):
        """第一层方法"""

        def level2_nested():
            """嵌套函数（第二层）"""

            class Level3Class:
                """嵌套类（第三层）"""

                def level4_method(self):
                    """嵌套类的方法（第四层）"""
                    return "深度嵌套"

            return Level3Class()

        return level2_nested()

class Level3Class:
                """嵌套类（第三层）"""

                def level4_method(self):
                    """嵌套类的方法（第四层）"""
                    return "深度嵌套"

